queries:
SELECT AVG(derived_total_cost * 1.0 / derived_product_cost), COUNT(*) FROM Invoice_Line_Items GROUP BY invoice_number
SELECT invoice_number, SUM(derived_total_cost) / SUM(derived_product_cost), COUNT(*) FROM Invoice_Line_Items GROUP BY invoice_number
SELECT invoice_number, AVG(derived_total_cost) * 1.0 / AVG(derived_product_cost) AS ratio, COUNT(*) AS line_item_count FROM Invoice_Line_Items GROUP BY invoice_number;
SELECT AVG(item_count) FROM (SELECT invoice_number, COUNT(DISTINCT order_item_id) AS item_count FROM Invoice_Line_Items GROUP BY invoice_number);
SELECT AVG(ratio) FROM (SELECT SUM(derived_total_cost) * 1.0 / COUNT(DISTINCT product_id) AS ratio FROM Invoice_Line_Items GROUP BY invoice_number);
SELECT AVG(ratio) FROM (SELECT SUM(derived_total_cost) * 1.0 / NULLIF(SUM(CAST(product_quantity AS REAL)), 0) AS ratio FROM Invoice_Line_Items GROUP BY invoice_number);
